package org.apache.commons.lang3.math;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_16_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Test with uppercase hexadecimal prefix
        String hexNumber = "0X1A";
        try {
            Number result = NumberUtils.createNumber(hexNumber);
            assertTrue("Expected an instance of Integer", result instanceof Integer);
            assertEquals("Expected value 26", 26, result.intValue());
        } catch (NumberFormatException e) {
            fail("NumberFormatException was thrown for a valid hexadecimal number with uppercase prefix");
        }
    }
}

